static NSError *GE(NSString *s){return [NSError errorWithDomain:@"Dylix.GitConflicts" code:1 userInfo:@{NSLocalizedDescriptionKey:s}];}
static NSString *Token(NSString *root,NSDictionary *status,NSArray *conflicts){NSMutableArray *files=[NSMutableArray new];for(NSDictionary *c in conflicts)[files addObject:@[c[@"path"],c[@"fingerprint"]]];NSData *json=[NSJSONSerialization dataWithJSONObject:@[status[@"head"]?:@"",status[@"state"]?:@0,files,TFAIDigest([NSData dataWithContentsOfFile:[root stringByAppendingPathComponent:@".git/index"]]),TFAIDigest([NSData dataWithContentsOfFile:[root stringByAppendingPathComponent:@".git/MERGE_HEAD"]])] options:NSJSONWritingSortedKeys error:nil];return TFAIDigest(json);}
NSDictionary *TFAIGitConflictAction(NSString *root,NSDictionary *args,NSError **error){
 if(!root.length){if(error)*error=GE(DXLoc(@"请先选择项目"));return nil;}TMCGitLease *lease __attribute__((objc_precise_lifetime))=[TMCGitLease tryWrite];if(!lease||[TMCGitLease isBuilding:root]){if(error)*error=GE(DXLoc(@"项目正在处理，请稍后操作 Git"));return nil;}
 TMCGitService *git=[[TMCGitService alloc]initWithRoot:root];NSDictionary *status=[git status:error];if(!status)return nil;NSArray *conflicts=[git conflicts:error];if(!conflicts)return nil;NSString *token=Token(root,status,conflicts),*action=args[@"action"];
 if([action isEqual:@"git_conflicts"]){NSUInteger offset=MIN([args[@"offset"] unsignedIntegerValue],conflicts.count);NSMutableArray *items=[NSMutableArray new];for(NSUInteger i=offset;i<MIN(offset+50,conflicts.count);i++){NSDictionary *c=conflicts[i];if(!TFAIAllowedRelativePath(c[@"path"]))continue;[items addObject:@{@"path":c[@"path"],@"fingerprint":c[@"fingerprint"],@"oursDeleted":c[@"oursDeleted"],@"theirsDeleted":c[@"theirsDeleted"]}];}return @{@"conflicts":items,@"total":@(conflicts.count),@"next_offset":offset+50<conflicts.count?@(offset+50):NSNull.null,@"state_token":token,@"merging":status[@"merging"]?:@NO};}
 if([action isEqual:@"git_read_conflict"]){if(![@[@"base",@"ours",@"theirs"] containsObject:args[@"side"]]){if(error)*error=GE(DXLoc(@"请选择 base、ours 或 theirs"));return nil;}if(!TFAIAllowedRelativePath(args[@"path"])){if(error)*error=GE(DXLoc(@"请选择项目源码文件"));return nil;}for(NSDictionary *c in conflicts)if([c[@"path"] isEqual:args[@"path"]]){NSString *text=c[args[@"side"]];if(TFAIContainsSecret(text)){if(error)*error=GE(DXLoc(@"冲突内容包含疑似密钥，请在本机 Git 页面查看"));return nil;}NSArray *lines=[text componentsSeparatedByString:@"\n"];NSUInteger start=MAX(1,[args[@"start_line"] unsignedIntegerValue]),next=start,bytes=0;NSMutableArray *slice=[NSMutableArray new];for(NSUInteger i=start-1;i<lines.count&&slice.count<120;i++){NSUInteger size=[lines[i] lengthOfBytesUsingEncoding:NSUTF8StringEncoding]+1;if(bytes+size>16384)break;bytes+=size;[slice addObject:lines[i]];next=i+2;}if(!slice.count){if(error)*error=GE(DXLoc(@"行号超出范围或单行过长"));return nil;}return @{@"path":args[@"path"],@"side":args[@"side"],@"content":[slice componentsJoinedByString:@"\n"],@"start_line":@(start),@"next_line":next<=lines.count?@(next):NSNull.null,@"fingerprint":c[@"fingerprint"],@"state_token":token};}if(error)*error=GE(DXLoc(@"冲突已变化，请重新查询"));return nil;}
 if(![args[@"state_token"] isEqual:token]){if(error)*error=GE(DXLoc(@"仓库或冲突已变化，请重新 git_conflicts 后确认"));return nil;}
 BOOL ok=NO;NSString *commit=nil;
 if([action isEqual:@"git_resolve_conflict"]){if(!TFAIAllowedRelativePath(args[@"path"])||![@[@"ours",@"theirs",@"manual"] containsObject:args[@"choice"]]){if(error)*error=GE(DXLoc(@"冲突路径或处理方式无效"));return nil;}if([args[@"choice"] isEqual:@"manual"]&&(![args[@"text"] isKindOfClass:NSString.class]||[args[@"text"] lengthOfBytesUsingEncoding:NSUTF8StringEncoding]>256*1024||TFAIContainsSecret(args[@"text"]))) {if(error)*error=GE(DXLoc(@"手动合并内容应为256KB内的源码"));return nil;}ok=[git resolve:args[@"path"] choice:args[@"choice"] text:args[@"text"] expected:args[@"fingerprint"] error:error];}
 else if([action isEqual:@"git_finish_merge"]){if(![status[@"merging"] boolValue]||conflicts.count){if(error)*error=GE(DXLoc(@"请先解决全部冲突，再完成当前合并"));return nil;}NSDictionary *prefs=[TMCGitPreferences effective:root];commit=[git commit:args[@"message"] name:prefs[@"name"] email:prefs[@"email"] error:error];ok=commit!=nil;}
 else if([action isEqual:@"git_abort_merge"])ok=[git abortMerge:error];
 else if([action isEqual:@"git_merge_branch"])ok=[git mergeBranch:args[@"branch"] error:error];
 else{if(error)*error=GE(DXLoc(@"未知冲突操作"));return nil;}
 if(!ok)return nil;NSDictionary *after=[git status:error];NSArray *remaining=[git conflicts:error];if(!after||!remaining)return nil;return @{@"success":@YES,@"commit":commit?:@"",@"remainingConflicts":@(remaining.count),@"merging":after[@"merging"]?:@NO,@"state_token":Token(root,after,remaining),@"uploaded":@NO};
}
